		{ "🎖 Lv.{number1}  {number2} / {number3} XP\n💰 {number4} G   🎫 {number5}\n🔑{number6} (Free today {number7}/{number8})\n⚡ Power {number9}\n⚔ Sniper Rifle · Rusty Era +{number10}\n📍 Field (best: Zone {number11})", "🎖 Stufe {number1} {number2} / {number3} Erfahrungspunkte\n💰 {number4} G 🎫 {number5}\n🔑{number6} (Heute kostenlos {number7}/{number8})\n⚡ Kraft {number9}\n⚔ Scharfschützengewehr · Rostige Ära +{number10}\n📍 Feld (am besten: Zone {number11})" },
		{ "💰 Not enough gold. ({number1} needed) Earn gold at the dummy yard, field hunting, dungeons, or the Boss Rush", "💰 Nicht genug Gold. ({number1} nötig) Verdiene Gold auf dem Dummy-Platz, bei der Feldjagd, in Dungeons oder im Boss Rush" },
		{ "🥇 {player1}\n<font color='#ffe{number1}e'>⚡ {number2}</font> Lv.{number3}\n<font color='#{number4}ad{number5}ff'>Spell Tome · Mythic Era +{number6}</font>", "🥇 {player1}\n<font color='#ffe{number1}e'>⚡ {number2}</font> Stufe {number3}\n<font color='#{number4}ad{number5}ff'>Zauberbuch · Mythische Ära +{number6}</font>" },
		{ "🎖 Lv.{number1}  {number2} / {number3} XP\n💰 {number4} G   🎫 {number5}\n🔑{number6} (Free today {number7}/{number8})\n⚡ Power {number9}\n⚔ Spell Tome · Rusty Era +{number10}\n📍 Field (best: Zone {number11})", "🎖 Stufe {number1} {number2} / {number3} Erfahrungspunkte\n💰 {number4} G 🎫 {number5}\n🔑{number6} (Heute kostenlos {number7}/{number8})\n⚡ Kraft {number9}\n⚔ Zauberbuch · Rostige Ära +{number10}\n📍 Feld (am besten: Zone {number11})" },
		{ "Zone {number1} · Abyss\n🌀 Gate of the Abyss · Rec. ⚡{number2}\nDanger ☠☠☠☠☠☠☠☠\n🌀 New set from here: Abyss Dominion Set", "Zone {number1} · Abgrund\n🌀 Tor des Abgrunds · Rec. ⚡{number2}\nGefahr ☠☠☠☠☠☠☠☠\n🌀 Neues Set von hier: Abyss-Dominion-Set" },
		{ "⚠ The {number1}-hour cap was reached, so {number2} hours' worth couldn't be saved. You can raise the cap in the Shop", "⚠ Das Limit von {number1} Stunden wurde erreicht, daher konnten {number2} Stunden nicht gespeichert werden. Du kannst das Limit im Shop erhöhen" },
		{ "Zone {number1} · Forest\n🏰 Forest Castle Gate · Rec. ⚡{number2}\nDanger ☠☠\n🌲 New set from here: Forest's Blessing Set", "Zone {number1} · Wald\n🏰 Waldschloss-Tor · Empfohlen ⚡{number2}\nGefahr ☠☠\n🌲 Neues Set von hier: Wald-Segen-Set" },
		{ "Zone {number1} · Snowfield\n❄ Ice Palace Gate · Rec. ⚡{number2}\nDanger ☠☠☠☠☠\n❄ New set from here: Frost's Breath Set", "Zone {number1} · Schneefeld\n❄ Eispalast-Tor · Empfohlen ⚡{number2}\nGefahr ☠☠☠☠☠\n❄ Neues Set von hier: Frost-Atem-Set" },
		{ "enemies below {number1}% HP are executed · bosses take up to +{number2}% damage (all your damage) as their HP drops", "Gegner unter {number1} % LP werden hingerichtet · Bosse erleiden bis zu +{number2} % Schaden (all dein Schaden), wenn ihre LP sinken" },
		{ "Zone {number1} · Desert\n🏜 Desert Temple Entrance · Rec. ⚡{number2}\nDanger ☠☠☠☠\n🏜 New set from here: Desert Sun Set", "Zone {number1} · Wüste\n🏜 Eingang des Wühentempels · Empfohlen ⚡{number2}\nGefahr ☠☠☠☠\n🏜 Neues Set von hier: Wüsten-Sonnenuntergang" },
		{ "🏔 Hunting Field\n{number1} Meadow · {number2} Forest\n{number3} Wasteland · {number4} Desert\n{number5} Snowfield · {number6} Volcano\n{number7} Darklands · {number8} Abyss", "🏔 Jagdfeld\n{number1} Wiese · {number2} Wald\n{number3} Ödland · {number4} Wüste\n{number5} Schneefeld · {number6} Vulkan\n{number7} Dunkle Länder · {number8} Abgrund" },
		{ "Zone {number1} · Darklands\n🦇 Dark Castle Gate · Rec. ⚡{number2}\nDanger ☠☠☠☠☠☠☠\n🦇 New set from here: Dark Pact Set", "Zone {number1} · Dunkle Länder\n🦇 Dunkles Schloss-Tor · Empfohlen ⚡{number2}\nGefahr ☠☠☠☠☠☠☠\n🦇 Neues Set von hier: Dunkles Pakt-Set" },
		{ "Zone {number1} · Volcano\n🌋 Lava Fortress Gate · Rec. ⚡{number2}\nDanger ☠☠☠☠☠☠\n🌋 New set from here: Lava Heart Set", "Zone {number1} · Vulkan\n🌋 Lava-Festungstor · Rec. ⚡{number2}\nGefahr ☠☠☠☠☠☠\n🌋 Neues Set von hier: Lava-Herz-Set" },
		{ "🚧 Stuck at level {number1}! Go to Menu (B) → Skills & Growth tab (Passives · Training) to break through.", "🚧 Du steckst bei Stufe {number1} fest! Gehe zu Menü (B) → Tab Fähigkeiten & Wachstum (Passiv · Training), um durchzubrechen." },
		{ "Zone {number1} · Meadow\n🌾 Adventure Begins · Rec. ⚡{number2}\nDanger ☠\n🌾 New set from here: Meadow's Guard Set", "Zone {number1} · Wiese\n🌾 Das Abenteuer beginnt · Rec. ⚡{number2}\nGefahr ☠\n🌾 Neues Set von hier: Wiesen-Wächter-Set" },
		{ "Limit Breaker   Title 『Limit Breaker』\nDefeat {number1} bosses in one Boss Rush run\n{number2} / {number3}   Reward: 🎫 {number4}", "Limitbrecher-Titel 『Limit Breaker』\nBesiege {number1} Bosse in einem Boss-Rush-Lauf\n{number2} / {number3} Belohnung: 🎫 {number4}" },
		{ "🎖 Lv.{number1}  {number2} / {number3} XP\n💰 {number4} G   🎫 {number5}\n🔑{number6} (Free today {number7}/{number8})\n⚡ Power {number9}\n⚔ Sniper Rifle · Rusty Era +{number10}\n📍 Dungeon", "🎖 Stufe {number1} {number2} / {number3} Erfahrungspunkte\n💰 {number4} G 🎫 {number5}\n🔑{number6} (Heute kostenlos {number7}/{number8})\n⚡ Kraft {number9}\n⚔ Scharfschützengewehr · Rostige Ära +{number10}\n📍 Dungeon" },
		{ "🌱 Beginner's Boon: +{number1}% damage and -{number2}% damage taken until you clear Zone {number3} (it fades by Lv {number4})", "🌱 Anfänger-Bonus: +{number1}% Schaden und -{number2}% erlittener Schaden, bis du Zone {number3} abgeschlossen hast (er verschwindet bei Lv {number4})" },
		{ "🐾 Pet Lv.{number1}! New ability 🧲 Auto-Loot — Loot within a {number2} radius gets pulled in automatically", "🐾 Haustier-Lv.{number1}! Neue Fähigkeit 🧲 Auto-Beute – Beute innerhalb eines {number2}-Radius wird automatisch eingesammelt" },
		{ "Boss Hunter   Title 『Boss Hunter』\nDefeat {number1} bosses in one Boss Rush run\n{number2} / {number3}   Reward: 🎫 {number4}", "Boss-Jäger-Titel 『Boss-Jäger』\nBesiege {number1} Bosse in einem Boss-Rush-Lauf\n{number2} / {number3} Belohnung: 🎫 {number4}" },
		{ "Unbreakable   Title 『Unbreakable』\nSurvive {number1} seconds in the Boss Rush\n{number2} / {number3}   Reward: 🎫 {number4}", "Unzerbrechlicher Titel 『Unzerbrechlich』\nÜberlebe {number1} Sekunden im Boss-Angriff\n{number2} / {number3} Belohnung: 🎫 {number4}" },
		{ "Reduces training / breakthrough wait time by {number1} min (the skip bar fills instantly)", "Verkürzt die Wartezeit für Training/Durchbruch um {number1} Minuten (die Überspringleiste füllt sich sofort)" },
		{ "Survivor   Title 『Survivor』\nSurvive {number1} seconds in the Boss Rush\n{number2} / {number3}   Reward: 🎫 {number4}", "Überlebender-Titel 『Überlebender』\nÜberlebe {number1} Sekunden im Boss-Angriff\n{number2} / {number3} Belohnung: 🎫 {number4}" },
		{ "First Dungeon   Title 『Dungeon Newbie』\nClear {number1} dungeon(s)\n{number2} / {number3}   Reward: {number4} G + 🎫 {number5}", "Erster Dungeon-Titel: 『Dungeon-Anfänger』\n{number1} Dungeons abschließen\n{number2} / {number3} Belohnung: {number4} G + 🎫 {number5}" },
		{ "Golden Hunter   Title 『Lucky Hunter』\nDefeat {number1} Golden Goblin(s)\n{number2} / {number3}   Reward: {number4} G", "Goldener Jäger Titel 『Glücklicher Jäger』\nBesiege {number1} goldene Goblins\n{number2} / {number3} Belohnung: {number4} G" },
		{ "💰 You have {number1} G left! Upgrade your weapon at the town anvil to get much stronger", "💰 Du hast noch {number1} G! Verbessere deine Waffe am Amboss in der Stadt, um viel stärker zu werden" },
		{ "Golden Thief   Title 『Golden Thief』\nDefeat {number1} Golden Goblin(s)\n{number2} / {number3}   Reward: 🎫 {number4}", "Goldener Dieb Titel 『Goldener Dieb』\nBesiege {number1} goldene Goblins\n{number2} / {number3} Belohnung: 🎫 {number4}" },
		{ "✨ Stat points +{number1}! {number2} unspent (press T to raise move speed / range / double shot)", "✨ Statuspunkte +{number1}! {number2} unverteilt (drücke T, um Lauftempo / Reichweite / Doppelschuss zu erhöhen)" },
		{ "Abyss Conqueror   Title 『Abyss Conqueror』\nClear field zone {number1}\n{number2} / {number3}   Reward: 🎫 {number4}", "Abgrund-Eroberer Titel 『Abgrund-Eroberer』\nFeldzone {number1} löschen\n{number2} / {number3} Belohnung: 🎫 {number4}" },
		{ "Sets obtained {number1} / {number2}  ·  Monsters / lord of that zone drop them at a set rate", "Erhaltene Sets {number1} / {number2}  ·  Monster / Lord dieser Zone lassen sie mit einer bestimmten Rate fallen" },
		{ "🔒 Defeat the Lord of Zone {number1} first — only then will the portal open for you.", "🔒 Besiege zuerst den Lord von Zone {number1} – erst dann öffnet sich das Portal für dich." },
		{ "💰 A Golden Goblin appeared in Zone {number1} · Meadow! Catch it for a jackpot! ({number2}s)", "💰 Ein goldener Goblin ist in Zone {number1} · Wiese aufgetaucht! Fange ihn für einen Jackpot! ({number2}s)" },
		{ "Allocate Stats\nSpend {number1} stat points (T key / Stats button)\n{number2} / {number3}   Reward: {number4} G", "Statistiken zuweisen\nGib {number1} Statistikpunkte aus (T-Taste / Statistik-Button)\n{number2} / {number3} Belohnung: {number4} G" },
		{ "Skilled Warrior   Title 『Veteran』\nReach character level {number1}\n{number2} / {number3}   Reward: 🎫 {number4}", "Geschickter Krieger Titel 『Veteran』\nErreiche Charakterstufe {number1}\n{number2} / {number3} Belohnung: 🎫 {number4}" },
		{ "Mythic Master   Title 『Mythic Master』\nObtain Mythic gear\n{number1} / {number2}   Reward: 🎫 {number3}", "Mythischer Meister-Titel 『Mythischer Meister』\nErhalte mythische Ausrüstung\n{number1} / {number2} Belohnung: 🎫 {number3}" },
		{ "Dummy Slayer   Title 『Dummy Slayer』\nHit the dummy {number1} times\n{number2} / {number3}   Reward: {number4} G", "Dummy-Mörder-Titel 『Dummy-Mörder』\nSchlage den Dummy {number1} Mal\n{number2} / {number3} Belohnung: {number4} G" },
		{ "🎟 {number1} free entries today · 🗝 {number2} keys!\nChallenge the dungeon at the north gate", "🎟 {number1} kostenlose Einträge heute · 🗝 {number2} Schlüssel!\nFordere den Kerker am Nordtor heraus" },
		{ "Unique effects found {number1} / {number2}  ·  Mythic gear can carry one (about {number3}% chance)", "Gefundene einzigartige Effekte {number1} / {number2}  ·  Mythische Ausrüstung kann einen tragen (ca. {number3}% Chance)" },
